import json

# Let me look at the actual JSON data to see all the table entries
with open('/app/resources/treasury_bulletin_1982_03.json', 'r') as f:
    data = json.load(f)

# Find the MQ-1 table (Treasury Bills)
def find_mq1(data):
    if isinstance(data, dict):
        for key, value in data.items():
            if 'MQ-1' in key or 'Treasury Bills' in str(key):
                return value
            result = find_mq1(value)
            if result is not None:
                return result
    elif isinstance(data, list):
        for item in data:
            result = find_mq1(item)
            if result is not None:
                return result
    return None

mq1 = find_mq1(data)
if mq1:
    print("Found MQ-1 data!")
    print(json.dumps(mq1, indent=2)[:3000])
else:
    print("Looking for MQ data in the JSON...")
    # Search for relevant keys
    for key in data.keys() if isinstance(data, dict) else []:
        if 'MQ' in key or 'treasury' in key.lower():
            print(f"Key: {key}")
